import shutil
import subprocess
from pathlib import Path

import pytest

from code_audit_mcp.config import Config
from code_audit_mcp.core import Context, Unit
from code_audit_mcp.engines import dart, shared

PUBSPEC_LOCK = """\
# Generated by pub
packages:
  http:
    dependency: "direct main"
    description:
      name: http
      sha256: "abc"
      url: "https://pub.dev"
    source: hosted
    version: "0.13.0"
  async:
    dependency: transitive
    description:
      name: async
      url: "https://pub.dev"
    source: hosted
    version: "2.11.0"
  flutter:
    dependency: "direct main"
    description: flutter
    source: sdk
    version: "0.0.0"
  my_utils:
    dependency: "direct main"
    description:
      path: "../utils"
      relative: true
    source: path
    version: "1.0.0"
sdks:
  dart: ">=3.0.0 <4.0.0"
"""


def test_parse_pubspec_lock_only_hosted() -> None:
    packages, direct = dart.parse_pubspec_lock(PUBSPEC_LOCK)
    assert sorted(packages) == [("async", "2.11.0"), ("http", "0.13.0")]
    assert direct == {"http"}


def test_pubspec_locks_skip_build_and_hidden_dirs(tmp_path: Path) -> None:
    for rel in ("pubspec.lock", "example/pubspec.lock", "build/x/pubspec.lock", ".dart_tool/pubspec.lock"):
        (tmp_path / rel).parent.mkdir(parents=True, exist_ok=True)
        (tmp_path / rel).write_text("")
    unit = Unit("dart", tmp_path, "Flutter", ".")
    assert [p.relative_to(tmp_path).as_posix() for p in dart.pubspec_locks(unit)] == ["example/pubspec.lock",
                                                                                     "pubspec.lock"]


def test_osv_findings_dedupes_aliases_and_extracts_fix() -> None:
    vuln = {"id": "GHSA-4rgh", "aliases": ["CVE-2020-35669"], "summary": "header injection",
            "database_specific": {"severity": "MODERATE"},
            "affected": [{"package": {"name": "http", "ecosystem": "Pub"},
                          "ranges": [{"type": "ECOSYSTEM", "events": [{"introduced": "0"}, {"fixed": "0.13.3"}]}]}]}
    alias = {**vuln, "id": "CVE-2020-35669", "aliases": ["GHSA-4rgh"]}
    [f] = shared.osv_findings({("http", "0.13.0"): [vuln, alias]}, "Pub", "app/pubspec.lock", {"http"})
    assert (f["file"], f["rule"], f["severity"], f["fix"], f["direct"]) == (
        "app/pubspec.lock", "GHSA-4rgh", "medium", "upgrade to 0.13.3", True)
    assert f["message"] == "http 0.13.0: header injection"


def test_parse_dart_analyze(tmp_path: Path) -> None:
    ctx = Context(tmp_path.resolve(), Config())
    data = {"version": 1, "diagnostics": [
        {"code": "invalid_assignment", "severity": "ERROR", "problemMessage": "A value of type 'int'…",
         "correctionMessage": "Try changing the type.",
         "location": {"file": str(tmp_path / "lib" / "a.dart"), "range": {"start": {"line": 6}}}},
    ]}
    [f] = dart.parse_dart_analyze(data, ctx)
    assert (f["file"], f["line"], f["rule"], f["severity"], f["fix"]) == (
        "lib/a.dart", 6, "invalid_assignment", "medium", "Try changing the type.")


@pytest.mark.skipif(not shutil.which("dart"), reason="requires dart")
async def test_dart_analyze_on_project(tmp_path: Path) -> None:
    (tmp_path / "pubspec.yaml").write_text("name: demo\nenvironment:\n  sdk: ^3.0.0\n")
    (tmp_path / "lib").mkdir()
    (tmp_path / "lib" / "demo.dart").write_text(
        "import 'dart:io';\n\nvoid f() {\n  String s = 3;\n  print(s);\n}\n")
    unit = Unit("dart", tmp_path, "Dart", ".")
    ctx = Context(tmp_path.resolve(), Config())
    assert "skipped" in await dart.analyze(unit, ctx)  # without .dart_tool it does not run pub get on its own
    subprocess.run(["dart", "pub", "get", "--offline"], cwd=tmp_path, check=True, capture_output=True)
    result = await dart.analyze(unit, ctx)
    assert sorted(f["rule"] for f in result["findings"]) == ["invalid_assignment", "unused_import"]
